questionvariables.text:
/* exd: shortest exact decimal display of a terminating value (up to 3 d.p.) */
exd(v) := if integerp(v) then v else if integerp(10*v) then dispdp(float(v),1) else if integerp(100*v) then dispdp(float(v),2) else dispdp(float(v),3);
/* Design: same board as Reading quartiles from a cumulative frequency curve. k is never 25, 50 or 75; every position kn/100 is on a grid line. The count in (b) is a cumulative frequency reading, so its tolerance is one small square on that axis, dy = n/20. cnt and below are at least 12.6 apart on every list, more than 2*dy. Source: original. */
P: [[[10,18,24,13,8,7],20,70,37],[[11,15,20,14,14,6],10,20,47],[[5,7,16,24,6,2],0,10,47],[[12,22,23,11,10,2],20,70,37],[[6,7,13,24,20,10],0,70,17],[[3,5,19,22,23,8],0,80,43],[[4,18,20,14,2,2],20,20,33],[[19,21,15,12,9,4],30,80,47],[[14,16,21,17,10,2],20,30,57],[[11,13,13,14,23,6],20,30,47]];
ix: 1+rand(10);
f: P[ix][1];
a: P[ix][2];
k: P[ix][3];
v: P[ix][4];
w: 10;
L1: a;
cf: makelist(sum(f[i],i,1,t),t,1,length(f));
n: last(cf);
lcb: makelist(L1+(t-1)*w,t,1,length(f));
cb(p) := 1+length(sublist(cf,lambda([c],is(c<p))));
cfb(k) := if k=1 then 0 else cf[k-1];
gq(p) := lcb[cb(p)] + (p-cfb(cb(p)))/f[cb(p)]*w;
jx: makelist(a+10*t,t,0,6);
jy: append([0],cf);
xmin: if a=0 then 0 else a-10;
xmax: a+60;
dy: n/20;
cfat(v) := block([kk], kk: 1+floor((v-a)/10), cfb(kk)+(v-lcb[kk])/10*f[kk]);
pk: k*n/100;
Pk: gq(pk);
below: cfat(v);
cnt: n-below;
Pd: dispdp(float(floor(10^1*(Pk)+1/2)/10^1),1);
belowd: dispdp(float(floor(10^1*(below)+1/2)/10^1),1);
cntd: dispdp(float(floor(10^1*(cnt)+1/2)/10^1),1);
/* diagnostics */
Patk: gq(k);
Pcf: pk;
/* test values */
r0(u) := float(floor(u+1/2));
